import React, { Component } from 'react';
import PropTypes from 'prop-types';
import cx from 'classnames';
import Link from 'next/link';
import { Button } from '../components/Button';

export default class Header extends Component {
  static propTypes = {
    active: PropTypes.bool,
    children: PropTypes.node,
    className: PropTypes.string,
    href: PropTypes.oneOfType([
      PropTypes.string,
      PropTypes.elementType({
        id: PropTypes.number,
        value: PropTypes.any,
      }),
    ]),
  };

  render() {
    const { active, href, className, onClick } = this.props;
    return (
      <div style={{ display: 'block' }}>
        {href ?
          (
            <Link
              to={href}
              className={cx(
                active && [
                  isActive ? 'active' : '',
                  onClick ? 'active' : null,
                  className,
                ].join(' '),
                current && [
                  active && [
                    current === href ? active[0] : undefined,
                    ...active.split(' '),
                  ],
                  href || current,
                ]
              )}
            >
              {active ? <a href={href} target="_blank" rel="noopener noreferrer" className={cx(isActive && [isActive])}>{children}</a> : null}
            </Link>
          ) : (
            <Button variant="contained" color="primary" onClick={onClick} className={cx(active, !href || active === href ? undefined : '')}>
              {children}
            </Button>
          )}
        </div>
      </div>
    );
  }
}

