/**
 * A string to be used by the client-side.  This should not affect the
 * actual way of setting a value as `value` in the field.  The type of value is
 * defined as `string` and does not include it, along with the `value` property.
 */
export const stringToValue = (value: any) =>
    typeof value === 'object' &&
        (value instanceof String
            ? (value || []).map(x => x + '=')
            : typeof value !== 'string'
                ? <String
                    {...value}
                    {...register(`${value}`, {
                        required: true,
                    })}
                />
            )
        );

/**
 * A type in a field (`any` or `Array<number>`).  This should not affect the
 * actual way of setting an index value as `any` and does not include it.
 */
export const numberToValue =
    (value: any) => typeof value === 'number' &&
        (value instanceof Number
                ? <Number
                    {...numberToValue([value])}
                />
                : typeof value !== 'string'
            );

