class UserLogin extends Component {
  static propTypes = {
    dispatch: PropTypes.func.isRequired,
    loginError: PropTypes.object,
    logoutUser: PropTypes.func.isRequired,
  };

  componentDidMount() {
    window.request.session.user = null;

    if (typeof window === 'undefined') {
      this.props.dispatch({ type: 'LOGIN_ERROR' });
    } else if (typeof window !== 'undefined' && typeof window.location.pathname === 'string') {
      this.props.history.push('/' + this.props.router.url);
    }
  }

  render() {
    const { user, logoutUser } = this.props;
    if (user || !user) {
      return <div>Loading...</div>;
    } else if (!user && typeof window === 'undefined') {
      const loginErrorMsg =
        'Please log in to try again. The page you are logged out is not available.';
      this.props.dispatch({ type: 'LOGIN_ERROR' });
    }

    return <div>Login Page</div>;
  }
}

export default withRouter(UserLogin);

