export default class TextInputContainer extends React.Component{

  static propTypes = {
    style? : ViewStyle.container
  }


  constructor(props) {
    super(props);

    this.state = {
      inputValue: '',
      textStyle: null,
      keyboardType: false,
      disabledTextStyle: null,
      showTextInput: true
    }
  }

  static propTypes = {
    style? : ViewStyle.container,
    onPress: React.PropTypes.func,
    textStyle: TextInput.propTypes.style,
    inputValue: React.PropTypes.string,
    keyboardType: PropTypes.any
  };


  getInputData(){
    return this.props.data;
  }

  render() {
    let textStyle = '';

    if (Platform.OS == "ios" && !this.state.disabledTextStyle) {
      textStyle += '-moz-only';
    }
    else if (Platform.OS == "android" && this.state.inputValue){
      textStyle+='-o-only';
      if(this.props.textStyle==null || textStyle==''){
        textStyle = '';
      }
    }

    return (
      <View style={[styles.container, { backgroundColor: this.state.textColor }]}>
          {this.getInputData()}
      </View>
    )
  }
}

