import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateRoomDto } from './dto/create-room.dto';
import { UpdateRoomDto } from './dto/update-room.dto';
import { Room } from 'src/models/room.entity';
@Injectable()
export class RoomService {
    constructor(
        @InjectRepository(Room)
        private roomRepository: Repository<Room>,
    ) {}

    async create(createRoomDto: CreateRoomDto): Promise<Room> {
        return this.roomRepository.save(createRoomDto);
    }

    async findOneById(id: number): Promise<Room> {
        if (!this.roomRepository.exists({ id })) return null;
        const room = await this.roomRepository.findOne({ where: { id } });
        return room;
    }

    async update(id: string, updateRoomDto: UpdateRoomDto): Promise<Room> {
        const updatedRoom = await this.roomRepository.update(id, updateRoomDto);

        if (!updatedRoom) return null;

        const lobby = Object.assign({}, updatedRoom, Object.assign({ id } as Room));
        this.roomRepository.save(lobby);

        return this.roomRepository.findOne(id);
    }

    async delete(id: string) {
        const lobby = await this.roomRepository.delete(id);

        if (!lobby) return null;

        this.roomRepository.remove(lobby);

        return this.roomRepository.findOne({ where: { id },relations: ['players'] })
    }
}

