@Component({
    selector: 'my-app',
    templateUrl: './app.component.html',
    styleUrls: ['./app.component.css']
})
export class AppComponent {
    modalRef: NgbModal;
    constructor(public modalService: NgbModal, public modalRef: NgbModal) {
        this.modalRef = modalRef;
    }

    openDialog() {
        const dialogRef = this.modalRef.create(null!);
        dialogRef.componentInstance.isOpen = true;

        return dialogRef.afterClosed().subscribe(close => {
            if (close === false) {
                this.dialogRef.close();
            } else {
                this.closeService.closeDialog();
            }
        });
    }

    closeDialog(): void {
        /*
         * This function is called when a dialog can be opened to close the modal, but we want to keep this component as in it.
         * In particular cases we should ensure that `open` becomes false or False. If so, we have to close ourmodal with `false`
         * if it's not already open and there is no way to do anything here when the user ended up, it has been called.
         */
        this.close();
    }
}

