import { Injectable, NestMiddleware } from '@nestjs/common';
import { AuthService } from '../auth.service';
import { StrategyOptions } from './strategy-options';
import * as jwt_decode from 'jwt-decode';

const JWT_SECRET = process.env.JWT_SECRET || 'secret';

@Injectable()
export class AuthGuard implements NestMiddleware<StrategyOptions> {
    async signUp(req: StrategyOptions, res: Response, next: any) {
        try {
            let token = jwt_decode.sign({
                username: req.body.username,
                password: <PASSWORD>,
                pass: parseInt(req.headers['x-jwt-token'], 10) // 0 means JWT is no longer valid, so the user should have a secret
            });

            try {
                const user = jwt_decode.user({
                    username: req.body.username || 'test',
                    pass: <PASSWORD>,
                    pem: parseInt(req.headers['x-jwt-token'], 10) // 0 means JWT is no longer valid, so the user should have a secret
                });

                if (user !== null && jwt_decode.verifyToken(req.body.secret, user.pem)) {
                    next();
                    return;
                }
            } catch (err) {
                next();
            }
        } catch (e) {
            next(e);
        }
    }
}

