def get_search_url(term):
    """Helper function to return a URL from the ``urllib.parse's \
        search.url(search_string=term).url()
    """
    if '?' in term:
        return "&" + term
    else:
        return None


def get_search_quote(term):
    """Helper function to return a string for searching the given `` term``
    if ``True`` and ``False`` are not supported, and ``False`` is
    used.
    """
    for url in get_search_url(term):
        return "%s?%s" % (url, urlencode_escape(term))

